import re, sys

def parse_table(lines):
    rows = []
    for l in lines:
        l = l.strip()
        if not l.startswith('|'):
            continue
        if set(l.replace('|','').replace('-','').strip()) == set():
            continue
        cells = [c.strip() for c in l.strip('|').split('|')]
        rows.append(cells)
    return rows

def is_sep(row):
    return all(re.fullmatch(r'-+', c) or c=='' for c in row)

def clean_stats_block(block_lines):
    rows = parse_table(block_lines)
    rows = [r for r in rows if not is_sep(r)]
    capacity = None
    start_date = None
    end_date = None
    header_idx = None
    for i, r in enumerate(rows):
        joined = ' '.join(r)
        m = re.search(r'ظرفیت کاری اسپرینت:\s*([\d.]+)\s*ساعت', joined)
        if m:
            capacity = m.group(1)
        if 'تاریخ پایان' in r or 'تاریخ شروع' in r:
            # figure out values adjacent
            for j,c in enumerate(r):
                if c == 'تاریخ پایان':
                    # value likely before it
                    for k in range(j-1,-1,-1):
                        if r[k]:
                            end_date = r[k]; break
                if c == 'تاریخ شروع':
                    for k in range(j-1,-1,-1):
                        if r[k]:
                            start_date = r[k]; break
            continue
        if r and r[0] == 'شخص':
            header_idx = i
            break
    data_rows = rows[header_idx:] if header_idx is not None else []
    # drop fully empty columns across data_rows
    if data_rows:
        ncols = len(data_rows[0])
        keep = []
        for c in range(ncols):
            if any(row[c].strip() for row in data_rows):
                keep.append(c)
        cleaned = [[row[c] for c in keep] for row in data_rows]
    else:
        cleaned = []
    return capacity, start_date, end_date, cleaned

def to_md_table(rows):
    if not rows:
        return ''
    out = ['| ' + ' | '.join(rows[0]) + ' |']
    out.append('|' + '|'.join(['---']*len(rows[0])) + '|')
    for r in rows[1:]:
        out.append('| ' + ' | '.join(r) + ' |')
    return '\n'.join(out)

if __name__ == '__main__':
    path = sys.argv[1]
    text = open(path, encoding='utf-8').read()
    # split by ### headers
    sections = re.split(r'(?m)^### ', text)
    stats_section = None
    for s in sections:
        if s.startswith('اطلاعات آماری'):
            stats_section = s
            break
    lines = stats_section.split('\n')[1:]
    capacity, start, end, cleaned = clean_stats_block(lines)
    print('CAPACITY:', capacity)
    print('START:', start)
    print('END:', end)
    print(to_md_table(cleaned))

