        l = l.rstrip('\n')
        if not l.strip().startswith('|'):
            continue
        cells = [c.strip() for c in l.strip().strip('|').split('|')]
        rows.append(cells)
    return rows

def is_sep(row):
    return all(re.fullmatch(r'-+', c) or c == '' for c in row)

def clean_stats_block(block_lines):
    rows = parse_table_lines(block_lines)
    rows = [r for r in rows if not is_sep(r)]
    capacity = None
    start_date = None
    end_date = None
    header_idx = None
    for i, r in enumerate(rows):
        joined = ' '.join(r)
        m = re.search(r'ظرفیت کاری اسپرینت:\s*([\d.]+)\s*ساعت', joined)
        if m:
            capacity = m.group(1)
        if 'تاریخ پایان' in r or 'تاریخ شروع' in r:
            for j, c in enumerate(r):
                if c == 'تاریخ پایان':
                    for k in range(j - 1, -1, -1):
                        if r[k]:
                            end_date = r[k]
                            break
                if c == 'تاریخ شروع':
                    for k in range(j - 1, -1, -1):
                        if r[k]:
                            start_date = r[k]
                            break
            continue
        if r and r[0] == 'شخص':
            header_idx = i
            break
    data_rows = rows[header_idx:] if header_idx is not None else []
    if data_rows:
        ncols = len(data_rows[0])
        keep = [c for c in range(ncols) if any(row[c].strip() for row in data_rows)]
        cleaned = [[row[c] for c in keep] for row in data_rows]
    else:
        cleaned = []
    return capacity, start_date, end_date, cleaned

def to_md_table(rows):
    if not rows:
        return '_(جدول خالی است)_'
    out = ['| ' + ' | '.join(rows[0]) + ' |']
    out.append('|' + '|'.join(['---'] * len(rows[0])) + '|')
    for r in rows[1:]:
        out.append('| ' + ' | '.join(r) + ' |')
    return '\n'.join(out)

def get_section(text, name):
    sections = re.split(r'(?m)^### ', text)
    for s in sections:
        if s.startswith(name):
            # strip the name line itself
            lines = s.split('\n')
            return '\n'.join(lines[1:]).strip('\n')
    return None

def load_source(fname):
    path = os.path.join(SRC_DIR, fname)
    return open(path, encoding='utf-8').read()

def build(fname, frontmatter, title, info_callout, summary_block, retro_note_prefix=None):
    text = load_source(fname)
    stats_raw = get_section(text, 'اطلاعات آماری')
    capacity, start, end, cleaned = clean_stats_block(stats_raw.split('\n'))
    stats_meta_lines = []
    if capacity:
        stats_meta_lines.append(f"- **ظرفیت کاری اسپرینت:** {capacity} ساعت")
    if start:
        stats_meta_lines.append(f"- **تاریخ شروع (شمسی):** {start}")
    if end:
        stats_meta_lines.append(f"- **تاریخ پایان (شمسی):** {end}")
    stats_meta = '\n'.join(stats_meta_lines)
    stats_table = to_md_table(cleaned)

    plan_table = get_section(text, 'برنامه کاری')
    report_table = get_section(text, 'گزارش کاری')
    retro = get_section(text, 'جلسه reterospective')

    parts = []
    parts.append('---')
    for k, v in frontmatter.items():
        parts.append(f"{k}: {v}")
    parts.append('---')
    parts.append('')
    parts.append(f"# {title}")
    parts.append('')
    parts.append(info_callout)
    parts.append('')
    parts.append(summary_block)
    parts.append('')
    parts.append('## اطلاعات آماری')
    parts.append('')
    if stats_meta:
        parts.append(stats_meta)
        parts.append('')
    parts.append(stats_table)
    parts.append('')
    parts.append('## برنامه کاری')
    parts.append('')
    parts.append(plan_table if plan_table and plan_table.strip() else '_(جدولی برای این بخش ثبت نشده است)_')
    parts.append('')
    parts.append('## گزارش کاری')
    parts.append('')
    parts.append(report_table if report_table and report_table.strip() else '_(جدولی برای این بخش ثبت نشده است)_')
    parts.append('')
    parts.append('## جلسه بازنگری (Retrospective)')
    parts.append('')
    if retro_note_prefix:
        parts.append(retro_note_prefix)
        parts.append('')
    if retro and retro.strip():
        parts.append(retro)
    else:
        parts.append('_(برای این اسپرینت، یادداشتی در برگه جلسه بازنگری ثبت نشده است — برگه خالی بود.)_')
    parts.append('')

    return '\n'.join(parts)

if __name__ == '__main__':
    pass

